import mongoose from 'mongoose';
import { jsonOptions } from './shared/json.js';
import { searchable } from './shared/searchable.js';
import { lineItemSchema, totalsFields } from './shared/lineItem.js';
import { softDelete } from './shared/softDelete.js';

const { ObjectId } = mongoose.Schema.Types;

const quotationSchema = new mongoose.Schema(
  {
    // Generated by the server; never accepted from clients.
    quotationNumber: { type: String, required: true, unique: true, immutable: true },
    companyId: { type: ObjectId, ref: 'Company', required: true, index: true },
    contactId: { type: ObjectId, ref: 'Contact', index: true },
    opportunityId: { type: ObjectId, ref: 'Opportunity', index: true },
    quotationDate: { type: Date, required: true },
    validUntil: { type: Date },
    items: [lineItemSchema],
    // Calculated by the server (services/quotationTotals.js).
    ...totalsFields,
    notes: { type: String, trim: true, maxlength: 5000 },
    termsAndConditions: { type: String, trim: true, maxlength: 5000 },
    statusId: { type: ObjectId, ref: 'QuotationStatus', required: true, index: true },
    // Set by POST /quotations/:id/send.
    sentAt: { type: Date },
    sentTo: { type: String, trim: true },
    sentBy: { type: ObjectId, ref: 'User' },
    // The order generated from this quotation, if any. Set atomically, so a
    // quotation can never produce two orders.
    orderId: { type: ObjectId, ref: 'Order', default: null },
    createdBy: { type: ObjectId, ref: 'User' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        companyId: 'company',
        contactId: 'contact',
        opportunityId: 'opportunity',
        statusId: 'status',
        orderId: 'order',
        sentBy: 'sentByUser',
        createdBy: 'createdByUser',
      },
    }),
  }
);

softDelete(quotationSchema);

// Found by global search on these fields.
searchable(quotationSchema, ['quotationNumber']);

export default mongoose.model('Quotation', quotationSchema);
